    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'piccante-formaggiata', 'PICCANTE FORMAGGIATA', 'For those who love a bit of a kick, our Piccante Formaggiata pizza is a must-try. This pizza features a zesty tomato base loaded with crunchy onions, bell peppers, fresh tomatoes, and spicy jalapeños, all generously topped with double cheese for a mouthwatering finish.', 1199, null, 'PIZZA', true, true, false, false, 3),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'tofu-mediterraneo', 'TOFU MEDITERRANEO', 'Discover a delightful fusion of Mediterranean flavours with our Tofu Mediterraneo pizza. A rich tomato base is generously topped with marinated tofu cubes, sun-dried tomatoes, roasted red peppers, artichoke hearts, and a sprinkle of fresh oregano. This plant-based pizza offers a perfect balance of savoury and tangy notes, making it a delicious and healthy choice for all pizza lovers.', 1299, null, 'PIZZA', true, true, false, false, 4),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'a-bella-figliola', 'A BELLA FIGLIOLA', 'Fior di latte cheese, blanched asparagus tips, creamy goat cheese, red onion marmalade, mild chilli & lemon compote dressed with extra virgin oil.', 1199, null, 'PIZZA', true, true, false, false, 5),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'pizza-e-fantasia', 'PIZZA E FANTASIA', 'White base of ricotta and fior di latte cheese, courgettes, Isle of Wight tomatoes and capers finished with caramelised lemon zest. [Vegan cheese instead of mozzarella or as an extra topping £1.95]', 1199, null, 'PIZZA', true, true, false, false, 6),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'pizza-cacio-e-pepe', 'PIZZA CACIO E PEPE', 'White base pizza topped with fior di latte cheese, goat cheese, ricotta cheese and gorgonzola finished with freshly ground black pepper. [Add tomato sauce or rainbow cherry tomatoes for £1.95]', 1099, null, 'PIZZA', true, true, false, false, 7),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'alicella-sagliuta', 'ALICELLA SAGLIUTA', 'San Marzano tomato sauce, fior di latte cheese, Isle of Wight cherry tomatoes, Pantelleria capers, Nocellara olives, Cetara anchovies, garlic oil and fresh basil. [Add chilli & lemon compote for £1.95]', 1299, null, 'PIZZA', true, true, false, false, 8),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'verdure-fresche', 'VERDURE FRESCHE', 'Experience the freshness of our Verdure Fresche pizza, adorned with a vibrant mix of bell peppers, mushrooms, raw onions, juicy fresh tomatoes, and sweetcorn. Perfect for vegetable lovers, this pizza is a celebration of crisp, garden-fresh flavours on a classic tomato base.', 1099, null, 'PIZZA', true, true, false, false, 9),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'pepperoni-doppio-formaggio', 'PEPPERONI DOPPIO FORMAGGIO', 'Savour the ultimate cheesy delight with our Pepperoni Doppio Formaggio pizza. A robust tomato base is layered with spicy pepperoni and smothered in double cheese, delivering a rich and satisfying flavour in every slice. Perfect for cheese and meat lovers alike.', 1295, null, 'PIZZA', true, true, false, false, 10),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'o-core-e-napule', 'O CORE E NAPULE', 'Isle of Wight roasted tomato sauce, smoked garlic and Buffalo mozzarella, mushrooms, Nocellara olives, artichokes and roasted ham, finished Extra virgin oil & fresh parmesan', 1295, null, 'PIZZA', true, true, false, false, 11),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'pizza-do-putecaro', 'PIZZA DO PUTECARO', 'Lightly smoked beechwood spicy salami, Isle of Wight roasted tomato salsa, fior di latte cheese, red onion marmalade and crumble of gorgonzola dressed with ''nduja, mild chilli & lemon compote.', 1295, null, 'PIZZA', true, true, false, false, 12),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'pizza-bufala', 'PIZZA BUFALA', 'White base with Buffalo mozzarella, Parma ham, rainbow cherry tomatoes, shaved Parmesan cheese, basil & extra virgin olive oil. [Add rocket salad as an extra topping £1.95]', 1195, null, 'PIZZA', true, true, false, false, 13),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'lazzarella', 'LAZZARELLA', 'Beef Meat Ragout, fior di latte cheese, Buffalo meatballs, Buffalo Ricotta Cheese, basil and extra virgin olive oil.', 1295, null, 'PIZZA', true, true, false, false, 14),
    ((select id from menu_categories where slug = 'sourdough-pizza-calzone'), 'pollo-funghi-dolce', 'POLLO FUNGHI DOLCE', 'Indulge in our Pollo Funghi Dolce pizza, featuring a savoury tomato base topped with tender chicken, earthy mushrooms, and sweetcorn. A delightful combination that brings together rich flavours and a touch of sweetness in every bite.', 1295, null, 'PIZZA', true, true, false, false, 15),
